// Generate CREATE TABLE SQL DDL from a parsed schema, across a few dialects.
// Beyond quoting, dialects genuinely disagree on types that matter a lot to
// get right — e.g. SQL Server's `timestamp` is a rowversion column, not a
// date/time value, so leaving DBML's `timestamp` type as-is there would
// silently produce something else entirely.

const DIALECTS = {
  postgres: {
    quote: (name) => `"${name}"`,
    typeMap: {},
    nowKeyword: 'now()',
    increment: 'serial', // int -> SERIAL / bigint -> BIGSERIAL, no per-column suffix
  },
  mysql: {
    quote: (name) => `\`${name}\``,
    typeMap: {},
    nowKeyword: 'NOW()',
    increment: 'suffix',
    incrementSuffix: 'AUTO_INCREMENT',
  },
  mssql: {
    quote: (name) => `[${name}]`,
    typeMap: {
      boolean: 'BIT', bool: 'BIT',
      text: 'NVARCHAR(MAX)', longtext: 'NVARCHAR(MAX)',
      uuid: 'UNIQUEIDENTIFIER',
      json: 'NVARCHAR(MAX)', jsonb: 'NVARCHAR(MAX)',
      timestamp: 'DATETIME2', // SQL Server's own `timestamp` type is a rowversion, not a date/time
    },
    nowKeyword: 'GETDATE()',
    increment: 'suffix',
    incrementSuffix: 'IDENTITY(1,1)',
  },
  oracle: {
    quote: (name) => `"${name}"`,
    typeMap: {
      boolean: 'NUMBER(1)', bool: 'NUMBER(1)',
      varchar: 'VARCHAR2', char: 'CHAR',
      text: 'CLOB', longtext: 'CLOB',
      uuid: 'VARCHAR2(36)',
      json: 'CLOB', jsonb: 'CLOB',
    },
    nowKeyword: 'CURRENT_TIMESTAMP',
    increment: 'suffix',
    incrementSuffix: 'GENERATED BY DEFAULT AS IDENTITY',
  },
};

function quoteIdent(dialect, name) {
  return DIALECTS[dialect].quote(name);
}

// "billing.invoices" -> { schema: 'billing', name: 'invoices' }. "public" is the
// default schema, so public.users is just users.
function splitName(full) {
  const i = full.lastIndexOf('.');
  if (i === -1) return { schema: null, name: full };
  const schema = full.slice(0, i);
  return { schema: schema.toLowerCase() === 'public' ? null : schema, name: full.slice(i + 1) };
}

// Schema and table are quoted separately: "billing"."invoices", not "billing.invoices"
// (which would be one table with a dot in its name).
function quoteTable(dialect, full) {
  const { schema, name } = splitName(full);
  return schema ? `${quoteIdent(dialect, schema)}.${quoteIdent(dialect, name)}` : quoteIdent(dialect, name);
}

function createSchemaStatement(dialect, schema) {
  const q = quoteIdent(dialect, schema);
  if (dialect === 'postgres' || dialect === 'mysql') return `CREATE SCHEMA IF NOT EXISTS ${q};`;
  if (dialect === 'mssql') {
    const lit = (s) => s.replace(/'/g, "''");
    return `IF SCHEMA_ID(N'${lit(schema)}') IS NULL EXEC(N'CREATE SCHEMA ${lit(q)}');`;
  }
  return null; // Oracle: a schema is a user, created by a DBA, not by DDL like this
}

function mapType(dialect, rawType) {
  const d = DIALECTS[dialect];
  const m = rawType.trim().match(/^(\w+)\s*(?:\(([^)]*)\))?$/);
  if (!m) return rawType;
  const base = m[1].toLowerCase();
  const args = m[2];
  const mapped = d.typeMap[base];
  if (!mapped) return rawType;
  if (mapped.includes('(')) return mapped; // fixed-size mapped type, e.g. NUMBER(1)
  if (args !== undefined) return `${mapped}(${args})`;
  if (dialect === 'oracle' && base === 'varchar') return `${mapped}(255)`; // VARCHAR2 requires a length
  return mapped;
}

function resolveDefault(dialect, value, isBooleanColumn) {
  if (/^(now\(\)|current_timestamp)$/i.test(value)) return DIALECTS[dialect].nowKeyword;
  // SQL Server's BIT and Oracle's NUMBER(1) (boolean's stand-ins, neither has
  // a real boolean type pre-23c) don't accept TRUE/FALSE as literals.
  if (isBooleanColumn && (dialect === 'mssql' || dialect === 'oracle') && /^(true|false)$/i.test(value)) {
    return /^true$/i.test(value) ? '1' : '0';
  }
  if (/^-?\d+(\.\d+)?$/.test(value) || /^(true|false|null)$/i.test(value)) return value;
  // Standard SQL escapes an embedded quote by doubling it, not backslash -
  // a default like O'Brien would otherwise close the string literal early.
  return `'${value.replace(/'/g, "''")}'`;
}

export function toSQL(schema, dialect = 'postgres') {
  if (!DIALECTS[dialect]) dialect = 'postgres';
  const d = DIALECTS[dialect];
  const lines = [];

  const schemas = [...new Set(
    [...schema.tables, ...(dialect === 'postgres' ? schema.enums : [])]
      .map((t) => splitName(t.name).schema)
      .filter(Boolean),
  )];
  const schemaLines = schemas.map((name) => createSchemaStatement(dialect, name)).filter(Boolean);
  if (schemaLines.length) lines.push(...schemaLines, '');

  for (const en of schema.enums) {
    if (dialect === 'postgres') {
      lines.push(`CREATE TYPE ${quoteTable(dialect, en.name)} AS ENUM (${en.values.map((v) => `'${v}'`).join(', ')});`);
      lines.push('');
    }
  }

  for (const table of schema.tables) {
    lines.push(`CREATE TABLE ${quoteTable(dialect, table.name)} (`);
    const colLines = [];
    const pkCols = table.columns.filter((c) => c.pk).map((c) => c.name);

    for (const col of table.columns) {
      let type = mapType(dialect, col.type);
      let incrementSuffix = '';
      if (col.increment) {
        if (d.increment === 'serial') {
          type = /^bigint/i.test(col.type) ? 'BIGSERIAL' : /^int/i.test(col.type) ? 'SERIAL' : type;
        } else {
          incrementSuffix = ` ${d.incrementSuffix}`;
        }
      }
      let line = `  ${quoteIdent(dialect, col.name)} ${type}${incrementSuffix}`;
      if (col.notNull || col.pk) line += ' NOT NULL';
      if (col.unique) line += ' UNIQUE';
      if (col.default !== null && col.default !== undefined) {
        line += ` DEFAULT ${resolveDefault(dialect, col.default, /^bool/i.test(col.type))}`;
      }
      colLines.push(line);
    }
    if (pkCols.length) {
      colLines.push(`  PRIMARY KEY (${pkCols.map((c) => quoteIdent(dialect, c)).join(', ')})`);
    }
    lines.push(colLines.join(',\n'));
    lines.push(');');
    if (table.note) lines.push(`-- ${table.note}`);
    lines.push('');
  }

  for (const ref of schema.refs) {
    // many side gets the FK; '>' means from is many -> to is one
    let childTable = ref.fromTable, childCol = ref.fromColumn, parentTable = ref.toTable, parentCol = ref.toColumn;
    if (ref.type === '<') {
      childTable = ref.toTable; childCol = ref.toColumn; parentTable = ref.fromTable; parentCol = ref.fromColumn;
    }
    if (ref.type === '<>') {
      // many-to-many: skip auto FK generation (would need join table)
      continue;
    }
    const child = splitName(childTable);
    // A named ref (Ref fk_orders_customer: ...) names its constraint.
    const fkName = ref.name || `fk_${child.schema ? `${child.schema}_` : ''}${child.name}_${childCol}`;
    lines.push(
      `ALTER TABLE ${quoteTable(dialect, childTable)} ADD CONSTRAINT ${quoteIdent(dialect, fkName)} ` +
      `FOREIGN KEY (${quoteIdent(dialect, childCol)}) REFERENCES ${quoteTable(dialect, parentTable)} (${quoteIdent(dialect, parentCol)});`
    );
  }

  return lines.join('\n');
}
